function readSpeechText(body) {
  const text = body?.text_to_convert;
  return typeof text === "string" && /\S/.test(text) && [...text].length <= 4096 ? text : null;
}

function speechVoice(id) {
  if (typeof id !== "string" || !/^[A-Za-z0-9]{20}$/.test(id))
    throw new Error("Set an ElevenLabs voice ID from your Voice Library");
  return id;
}

const voiceId = "6WwXjDDEMyNmFG95zycZ";
const item = $input.first().json;
const text = /^application\/json(?:;|$)/i.test(item.headers?.["content-type"] ?? "")
  ? readSpeechText(item.body)
  : null;
return [
  {
    json: {
      valid: text !== null,
      ...(text === null
        ? {}
        : {
            url:
              "https://api.elevenlabs.io/v1/text-to-speech/" +
              speechVoice(voiceId) +
              "?output_format=mp3_44100_128",
            request: { text, model_id: "eleven_multilingual_v2" },
          }),
    },
  },
];

function checkSpeechBytes(bytes, mediaType) {
  const mime = typeof mediaType === "string" ? mediaType.split(";")[0].toLowerCase().trim() : "";
  if (
    !["audio/mpeg", "audio/mp3", "application/octet-stream"].includes(mime) ||
    bytes.length < 24 ||
    bytes.length > 8 * 1024 * 1024
  ) {
    throw new Error("The speech response is empty, has the wrong format, or exceeds 8 MiB");
  }
  let offset = 0;
  if (bytes[0] === 0x49 && bytes[1] === 0x44 && bytes[2] === 0x33) {
    const length = bytes.subarray(6, 10);
    if (length.some((byte) => byte > 0x7f))
      throw new Error("The speech response has an invalid MP3 tag");
    offset = 10 + ((length[0] << 21) | (length[1] << 14) | (length[2] << 7) | length[3]);
    if (bytes[3] === 4 && bytes[5] & 0x10) offset += 10;
  }
  // The selected output is MPEG-1 Layer III, 44.1 kHz. Check a complete first audio frame after optional ID3 metadata.
  const frame = bytes.subarray(offset, offset + 4);
  const bitrates = [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 0];
  const bitrate = bitrates[frame[2] >> 4];
  const frameSize = Math.floor((144000 * bitrate) / 44100) + ((frame[2] >> 1) & 1);
  if (
    frame.length !== 4 ||
    frame[0] !== 0xff ||
    (frame[1] & 0xfe) !== 0xfa ||
    ((frame[2] >> 2) & 3) !== 0 ||
    !bitrate ||
    offset + frameSize > bytes.length
  )
    throw new Error("The speech response has no complete first MP3 frame");
}

const item = $input.first();
if (item.json.statusCode !== 200 || !item.binary?.data)
  throw new Error("ElevenLabs did not return the complete MP3");
const bytes = await helpers.getBinaryDataBuffer(0, "data");
checkSpeechBytes(bytes, item.binary.data.mimeType);
return [
  {
    json: {},
    binary: { data: { ...item.binary.data, mimeType: "audio/mpeg", fileName: "speech.mp3" } },
  },
];
